// Enrutado y redaccion de los avisos de PorteriaYa.
//
// Aqui NO se calcula ninguna regla de negocio (§10): eso ya lo decidio Spring.
// Lo unico que pasa en este nodo es convertir un evento en un asunto y un
// cuerpo de correo. Si hace falta cambiar un plazo o un umbral, se cambia en
// las propiedades de Spring, no aqui.

const secretoEsperado = $env.PORTERIA_SECRET;
const salida = [];

for (const item of $input.all()) {
  const cabeceras = item.json.headers || {};
  const cuerpo = item.json.body || item.json;

  // El secreto compartido de §10. Si no cuadra, no se envia nada.
  if (secretoEsperado) {
    const recibido = cabeceras['x-porteria-secret'] || cabeceras['X-Porteria-Secret'];
    if (recibido !== secretoEsperado) {
      throw new Error('X-Porteria-Secret invalido: evento descartado');
    }
  }

  const tipo = cuerpo.tipo;
  const d = cuerpo.datos || {};
  const apto = d.apartamento || 'sin apartamento';

  let asunto;
  let texto;
  let destinatario = d.correoResidente || $env.CORREO_ADMINISTRACION || 'administracion@example.test';

  switch (tipo) {
    // ---------------------------------------------- flujo 1: visitas
    case 'AUTORIZACION_CREADA':
      asunto = `Codigo de ingreso para ${d.visitanteNombre}`;
      texto = [
        `Autorizaste el ingreso de ${d.visitanteNombre} al apartamento ${apto}.`,
        '',
        `CODIGO: ${d.codigo}`,
        '',
        `Valido desde ${d.validaDesde} hasta ${d.validaHasta}.`,
        'Comparte este codigo con tu visitante. En la porteria lo pediran junto',
        'con su nombre y los ultimos cuatro digitos del documento.'
      ].join('\n');
      break;

    case 'INGRESO_REGISTRADO':
      asunto = `${d.visitanteNombre} acaba de ingresar`;
      texto = [
        `${d.visitanteNombre} ingreso al apartamento ${apto}.`,
        `Registrado por ${d.vigilante} a las ${d.ingresoEn}.`,
        '',
        'Si no esperabas esta visita, avisa a la porteria.'
      ].join('\n');
      break;

    // ------------------------------------- flujo 2: aprobacion en vivo
    case 'VISITA_NO_ANUNCIADA':
      asunto = `${d.visitanteNombre} pide subir a tu apartamento`;
      texto = [
        `${d.visitanteNombre} esta en la porteria del conjunto.`,
        d.motivo ? `Motivo: ${d.motivo}` : '',
        '',
        'APROBAR:  ' + d.urlAprobar,
        'RECHAZAR: ' + d.urlRechazar,
        '',
        `Tienes hasta ${d.venceEn} para responder.`,
        'Si no respondes, la decision queda en manos del vigilante.',
        '',
        'Los enlaces abren una pagina de confirmacion y sirven una sola vez.'
      ].filter(Boolean).join('\n');
      break;

    // ----------------------------------------------- flujo 3: paquetes
    case 'PAQUETE_RECIBIDO':
      asunto = 'Tienes un paquete en porteria';
      texto = [
        `Llego un paquete para el apartamento ${apto}: ${d.descripcion}.`,
        d.remitente ? `Remitente: ${d.remitente}` : '',
        '',
        `CODIGO DE RETIRO: ${d.codigoRetiro}`,
        '',
        'Presenta este codigo en porteria, o pide que lo retire alguien que',
        'tengas registrado como autorizado.'
      ].filter(Boolean).join('\n');
      break;

    case 'PAQUETE_RECORDATORIO':
      asunto = `Recordatorio: paquete sin retirar (${d.hitoHoras} h)`;
      texto = [
        `El paquete "${d.descripcion}" sigue en porteria.`,
        `Lleva ${d.horasSinRetirar} horas sin retirar.`,
        '',
        'A los 7 dias se escala a la administracion.'
      ].join('\n');
      break;

    case 'PAQUETE_ESCALADO':
      asunto = `Paquete escalado: apartamento ${apto}`;
      texto = [
        `El paquete "${d.descripcion}" del apartamento ${apto} lleva`,
        `${d.diasSinRetirar} dias sin retirar y se escala a administracion.`,
        '',
        'Recibido el ' + d.recibidoEn
      ].join('\n');
      destinatario = $env.CORREO_ADMINISTRACION || 'administracion@example.test';
      break;

    // ------------------------------------ flujo 4: alertas de seguridad
    // Van a administracion, no al residente. En produccion este es el
    // ramal que deberia salir por Telegram: cambiar el nodo de correo
    // por uno de Telegram y nada mas.
    case 'PERSONA_NO_PERMITIDA':
      asunto = `ALERTA: intento de ingreso de persona no permitida (${apto})`;
      texto = [
        'Se nego el ingreso de una persona que esta en la lista de no permitidos.',
        '',
        `Visitante: ${d.visitanteNombre}`,
        `Apartamento destino: ${apto}`,
        `Motivo del registro: ${d.motivoRegistro}`,
        `Vigilante: ${d.vigilante}`,
        '',
        'Confirma por radio con la porteria.'
      ].join('\n');
      destinatario = $env.CORREO_ADMINISTRACION || 'administracion@example.test';
      break;

    case 'PERMANENCIA_EXCEDIDA':
      asunto = `Permanencia excedida en ${apto}`;
      texto = [
        `${d.visitanteNombre} lleva mas tiempo del esperado en el apartamento ${apto}.`,
        `Duracion esperada: ${d.duracionEsperadaMin} minutos. Ingreso: ${d.ingresoEn}.`,
        '',
        'Verifica por camaras o por ronda.'
      ].join('\n');
      destinatario = $env.CORREO_ADMINISTRACION || 'administracion@example.test';
      break;

    case 'SALIDA_NO_REGISTRADA':
      asunto = `Cierre automatico: salida no registrada (${apto})`;
      texto = [
        `El ingreso de ${d.visitanteNombre} al apartamento ${apto} se cerro`,
        'automaticamente sin registro de salida.',
        '',
        `Ingreso: ${d.ingresoEn}`
      ].join('\n');
      destinatario = $env.CORREO_ADMINISTRACION || 'administracion@example.test';
      break;

    // --------------------------------------------------- eventos del RAG
    case 'DOCUMENTO_INDEXADO':
      asunto = `Documento indexado: ${d.titulo}`;
      texto = `"${d.titulo}" (${d.tipo}, v${d.version}) quedo indexado con ${d.chunks} fragmentos.`;
      destinatario = $env.CORREO_ADMINISTRACION || 'administracion@example.test';
      break;

    case 'RAG_SIN_RESPUESTA':
      asunto = 'El asistente no encontro una respuesta';
      texto = [
        'Alguien pregunto algo que no esta en los documentos del conjunto:',
        '',
        `"${d.pregunta}"`,
        '',
        `Rol: ${d.rol}. Mejor similitud encontrada: ${d.mejorSimilitud}.`,
        '',
        'Conviene documentarlo.'
      ].join('\n');
      destinatario = $env.CORREO_ADMINISTRACION || 'administracion@example.test';
      break;

    default:
      // Un tipo desconocido no debe tumbar el flujo: se registra y se ignora
      asunto = `Evento sin plantilla: ${tipo}`;
      texto = JSON.stringify(cuerpo, null, 2);
      destinatario = $env.CORREO_ADMINISTRACION || 'administracion@example.test';
  }

  salida.push({ json: { tipo, destinatario, asunto, texto } });
}

return salida;
